import Link from "next/link";
import Image from "next/image";
import { Asset } from "@/data/mockData";
import { Download, ExternalLink } from "lucide-react";

interface AssetCardProps {
    asset: Asset;
}

const AssetCard = ({ asset }: AssetCardProps) => {
    return (
        <div className="premium-card group overflow-hidden flex flex-col h-full rounded-lg">
            <div className="relative aspect-video overflow-hidden border-b border-border">
                <Image
                    src={asset.previewUrl}
                    alt={asset.title}
                    fill
                    className="object-cover transition-transform duration-500 group-hover:scale-105"
                />
                <div className="absolute top-2 right-2">
                    <span className="bg-background/90 backdrop-blur-sm text-[10px] uppercase font-bold px-2 py-1 border border-border">
                        {asset.license}
                    </span>
                </div>
            </div>

            <div className="p-5 flex flex-col flex-grow">
                <div className="text-[10px] uppercase tracking-widest text-secondary font-bold mb-1">
                    {asset.category}
                </div>
                <h3 className="text-lg font-bold mb-2 group-hover:underline">
                    {asset.title}
                </h3>
                <p className="text-sm line-clamp-2 mb-6 flex-grow">
                    {asset.description}
                </p>

                <div className="mt-auto pt-4 flex items-center justify-between border-t border-border/50">
                    <Link
                        href={`/assets/${asset.id}`}
                        className="text-xs font-bold uppercase tracking-tight flex items-center hover:opacity-70 transition-opacity"
                    >
                        Details <ExternalLink size={12} className="ml-1" />
                    </Link>
                    <a
                        href={asset.downloadUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center space-x-2 bg-foreground text-background px-3 py-1.5 rounded text-xs font-bold hover:opacity-90 transition-opacity"
                    >
                        <Download size={14} />
                        <span>DOWNLOAD</span>
                    </a>
                </div>
            </div>
        </div>
    );
};

export default AssetCard;
